<?php
require_once 'config.php'; require_auth(); ensure_schema(); $pdo=db(); $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT code,public_token FROM work_orders WHERE id=?');$st->execute([$id]);$o=$st->fetch();if(!$o){http_response_code(404);exit('Orden no encontrada');}$url=public_base_url().'/track.php?t='.$o['public_token'];?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR <?=h($o['code'])?></title><style>body{font-family:Arial;background:#080808;color:#fff;text-align:center;padding:30px}.box{max-width:480px;margin:auto;background:#111;padding:28px;border-radius:22px}img{width:min(360px,80vw);background:#fff;padding:14px;border-radius:16px}button{padding:12px 18px;border:0;border-radius:10px;margin-top:15px}</style></head><body><div class="box"><h1><?=h(app_name())?></h1><h2><?=h($o['code'])?></h2><p>Escaneá para consultar el seguimiento.</p><img src="https://quickchart.io/qr?size=360&text=<?=rawurlencode($url)?>" alt="QR"><p><small><?=h($url)?></small></p><button onclick="window.print()">Imprimir QR</button></div></body></html>